import React from 'react';
import { Button } from '@fiverr-private/button';
import { raiseToastProps } from '../../raiseToast/types';
import raiseToast from '../../raiseToast';

const RaiseToastDemo = (props: raiseToastProps) => {
  const getText = () => {
    if (props.location) {
      return `Raise ${props.location} toast`;
    } else if (props.type) {
      return `Raise ${props.type} toast`;
    }
    return 'Raise toast';
  };

  return <Button onClick={() => raiseToast(props)}>{getText()}</Button>;
};

export default RaiseToastDemo;
